import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

test('source differs from the recorded guide baseline', async () => {
  const source = await readFile(new URL('../src/payments/index.ts', import.meta.url), 'utf8');
  const guide = await readFile(new URL('../.agents/knowledge/guides/payments.md', import.meta.url), 'utf8');
  assert.match(source, /limit = 20/);
  assert.match(guide, /sha256:000000/);
  assert.match(guide, /limit was 10/);
});
